(window.__quranSurahs=window.__quranSurahs||{})[86]={"nomPhon":"At-Taariq","versets":{"1":{"text":"Par le ciel et par l'astre nocturne","arabe":"وَٱلسَّمَآءِ وَٱلطَّارِقِ"},"2":{"text":"Et qui te dira ce qu'est l'astre nocturne?","arabe":"وَمَآ أَدْرَىٰكَ مَا ٱلطَّارِقُ"},"3":{"text":"C'est l'étoile vivement brillante.","arabe":"ٱلنَّجْمُ ٱلثَّاقِبُ"},"4":{"text":"Il n'est pas d'âme qui n'ait sur elle un gardien.","arabe":"إِن كُلُّ نَفْسٍۢ لَّمَّا عَلَيْهَا حَافِظٌۭ"},"5":{"text":"Que l'homme considère donc de quoi il a été créé.","arabe":"فَلْيَنظُرِ ٱلْإِنسَٰنُ مِمَّ خُلِقَ"},"6":{"text":"Il a été créé d'une giclée d'eau","arabe":"خُلِقَ مِن مَّآءٍۢ دَافِقٍۢ"},"7":{"text":"sortie d'entre les lombes et les côtes.","arabe":"يَخْرُجُ مِنۢ بَيْنِ ٱلصُّلْبِ وَٱلتَّرَآئِبِ"},"8":{"text":"Allah est certes capable de le ressusciter.","arabe":"إِنَّهُۥ عَلَىٰ رَجْعِهِۦ لَقَادِرٌۭ"},"9":{"text":"Le jour où les cœurs dévoileront leurs secrets,","arabe":"يَوْمَ تُبْلَى ٱلسَّرَآئِرُ"},"10":{"text":"Il n'aura alors ni force ni secoureur.","arabe":"فَمَا لَهُۥ مِن قُوَّةٍۢ وَلَا نَاصِرٍۢ"},"11":{"text":"Par le ciel qui fait revenir la pluie!","arabe":"وَٱلسَّمَآءِ ذَاتِ ٱلرَّجْعِ"},"12":{"text":"et par la terre qui se fend!","arabe":"وَٱلْأَرْضِ ذَاتِ ٱلصَّدْعِ"},"13":{"text":"Ceci [le Coran] est certes, une parole décisive [qui tranche entre le vrai et le faux],","arabe":"إِنَّهُۥ لَقَوْلٌۭ فَصْلٌۭ"},"14":{"text":"et non point une plaisanterie frivole!","arabe":"وَمَا هُوَ بِٱلْهَزْلِ"},"15":{"text":"Ils se servent d'une ruse,","arabe":"إِنَّهُمْ يَكِيدُونَ كَيْدًۭا"},"16":{"text":"et Moi aussi Je me sers de Mon plan.","arabe":"وَأَكِيدُ كَيْدًۭا"},"17":{"text":"Accorde (ô Prophète) donc un délai aux infidèles: accorde-leur un court délai.","arabe":"فَمَهِّلِ ٱلْكَٰفِرِينَ أَمْهِلْهُمْ رُوَيْدًۢا"}}};